import {MODELS,DATASETS,METHOD_CARDS} from './catalog.mjs';
import {fieldInfo,validateRows,selectUsableRows,finite} from '../agent/core.mjs';
import {partition,assertDisjoint,assertExperimentWritable} from './engine.mjs';
import * as trainer from './training.mjs';
import {esc,num,panel,chart,table,flow,field,readFile,download,downloadRows} from './ui.mjs';
const experiments=new Map();let modelId='boost',tab='data';
const state=()=>{if(!experiments.has(modelId))experiments.set(modelId,{dataset:MODELS.find(m=>m.id===modelId).dataset,sets:[[],[],[]],all:[],results:[],busy:false,origin:'尚未载入',fit:null,history:[],ratio:[70,15,15],method:'well-time',status:'等待数据',metrics:null});return experiments.get(modelId);};
export const currentExperiment=()=>({model:MODELS.find(m=>m.id===modelId),...state()});
function files(){return [['all','整体数据'],['0','训练集'],['1','验证集'],['2','测试集']].map(([role,name])=>`<div class="file-box"><label for="upload-${role}">${name}上传</label><small>CSV / JSON · ≤5MB · 字段见右侧</small><input id="upload-${role}" type="file" data-upload="${role}" accept=".csv,.json"></div>`).join('');}
const inlineFields={fraction:['小层比例','0–1'],permeability:['渗透率','毫达西'],thickness:['有效厚度','米'],porosity:['孔隙度','小数0–1'],connectivity:['连通强度','0–1'],measure_code:['措施编码','0酸化 / 1堵水 / 2调参'],incremental:['平均措施增油','标准立方米/日'],distance_m:['井间距离','米'],time_days:['注入后时间','天'],concentration:['示踪剂浓度','源浓度单位']};
function counts(s){return `<div class="counts">${['训练集','验证集','独立测试集'].map((n,i)=>`<div>${n}<b>${s.sets[i].length} <small>行</small></b></div>`).join('')}</div>`;}
export function renderStudio(){const m=MODELS.find(m=>m.id===modelId),s=state(),ds=DATASETS.find(d=>d.id===s.dataset);return `<div class="model-list">${MODELS.map(x=>`<button data-studio="model" data-id="${x.id}" class="${x.id===modelId?'active':''}">${esc(x.name)}</button>`).join('')}</div><div class="studio"><section class="panel"><div class="panel-head"><div><span class="section-label">MODEL STUDIO / ${esc(m.en)}</span><h2 style="font-size:20px;margin-top:5px">${esc(m.name)}</h2></div><span class="tag ${m.mode==='remote'?'blue':''}">${esc(m.tag)}</span></div><div class="panel-body"><p class="explanation">${esc(m.note)}</p><div class="subtabs">${[['data','01 数据与划分'],['train','02 训练与评价'],['calc','03 计算与导出']].map(([id,n])=>`<button data-studio="tab" data-id="${id}" class="${tab===id?'active':''}">${n}</button>`).join('')}</div>${s.error?`<div class="error-box" role="alert">${esc(s.error)}</div>`:''}${tab==='data'?dataView(m,s,ds):tab==='train'?trainView(m,s):calcView(m,s)}</div></section><aside class="grid">${panel('模型结构',`<div class="architecture">${m.structure.map((n,i)=>`<div class="arch-node"><span>${String(i+1).padStart(2,'0')}</span>${esc(n)}</div>${i<m.structure.length-1?'<div class="arch-arrow">↓</div>':''}`).join('')}</div>`,'<span class="tiny">PPT '+m.page+'</span>')}${panel('数学公式',`<div class="model-formula">${esc(m.formula)}</div>`)}${panel('参数解释与单位',table(m.parameters.map(([p,n,u])=>({p,n,u})),[['p','参数'],['n','解释'],['u','单位 / 默认值']]))}${panel('输入特征字典',table(m.required.map(k=>({k,n:(inlineFields[k]??fieldInfo[k]??[k,'见源数据'])[0],u:(inlineFields[k]??fieldInfo[k]??[k,'见源数据'])[1]})),[['k','字段'],['n','含义'],['u','中文单位']]))}</aside></div><section class="gap">${panel('决策方法与大模型工具链',`<div class="three">${METHOD_CARDS.map(x=>`<article class="method-card"><span class="section-label">PPT ${x.page}</span><h3>${x.name}</h3><code>${esc(x.formula)}</code><div style="margin:12px 0">${flow(x.structure)}</div><p class="tiny">${x.note}</p></article>`).join('')}</div>`)}</section>`;}
function dataView(m,s,ds){return `<div class="toolbar"><label>配套数据 <select id="studio-dataset">${DATASETS.map(d=>`<option value="${d.id}" ${d.id===s.dataset?'selected':''}>${d.name} · ${d.kind==='real'?'实测':'合成'}</option>`).join('')}</select></label><button class="btn primary" data-studio="load" ${s.busy?'disabled':''}>载入并划分</button><a class="btn" href="${ds.csv}" download>↓ 配套CSV</a></div><div class="note ${ds.kind==='real'?'green':''}">${esc(ds.source)} · ${esc(ds.note)}</div><div class="upload-grid">${files()}</div><div class="tool-form">${field('ratio0','训练集 %',s.ratio[0])}${field('ratio1','验证集 %',s.ratio[1])}${field('ratio2','测试集 %',s.ratio[2])}<label>划分方式<select id="split-method">${[['well-time','逐井按时间（推荐）'],['time','全局按时间'],['random','随机划分（事件/样本）'],['well','整井留出']].map(([v,n])=>`<option value="${v}" ${s.method===v?'selected':''}>${n}</option>`).join('')}</select></label></div><div class="row"><button class="btn" data-studio="split">按当前比例重新划分</button><button class="btn" data-studio="export-split">↓ 导出划分记录</button></div>${counts(s)}<p class="tiny">当前来源：${esc(s.origin)}。时间预测默认逐井按时间划分；随机划分不适用于评估未来预测。每个模型独立保存实验状态，刷新前请导出。</p><div class="schema">${m.required.map(k=>`<code>${esc(k)}</code>`).join('')}</div><p class="tiny">当前数据预览（前3行）</p><pre class="sample">${esc(JSON.stringify((s.all.length?s.all:s.sets.flat()).slice(0,3),null,2))}</pre>`;}
function metricView(s){if(!s.metrics)return '<div class="empty">暂无独立评价指标；需先训练，再选择验证集或测试集</div>';return `<div class="metric-grid">${Object.entries(s.metrics).map(([k,v])=>`<div><span>${esc(k)}</span><b>${num(v,k==='N'?0:4)}</b></div>`).join('')}</div>`;}
function resultView(s){if(!s.results.length)return '<div class="empty">暂无计算结果</div>';const rs=s.results,well=rs[0].well_id,rows=rs.filter(r=>r.well_id===well).slice(-100),numeric=rows.some(r=>typeof r.prediction==='number');return `${numeric?chart([{name:'观测值',values:rows.map(r=>r.actual),labels:rows.map(r=>r.date??r.sample_id??r.time_days),color:'#b58e51'},{name:s.fit?.id==='isolation'?'异常判定':'模型输出',values:rows.map(r=>r.prediction),color:'#aa2834',dash:true}],{unit:MODELS.find(m=>m.id===modelId).unit}):''}<p class="tiny">曲线预览对象：${esc(well)}；评价统计覆盖本批全部有效对象。共${rs.length}条，未覆盖${rs.filter(r=>r.prediction===null||r.prediction===undefined).length}条；表格显示前20条，导出包含全部。</p>${table(rs,[['well_id','井/对象'],['date','日期'],['actual','真实值'],['prediction','模型输出'],['score','异常分数'],['reason','未覆盖原因']],20)}`;}
function trainView(m,s){return `${counts(s)}<div class="note ${m.mode==='remote'?'red':''}">${esc(s.origin)}。${m.mode==='remote'?'XGBoost须连接独立Python服务。':'耗时由performance.now()实际计量；不会预填训练成功或评价指标。'}</div><div class="tool-form">${field('epochs','训练轮次（神经网络）',s.options?.epochs??10)}${field('trees','树数量（树模型）',s.options?.trees??30)}${field('depth','最大树深（树模型）',s.options?.depth??3)}</div><div class="row"><button class="btn primary" data-studio="train" ${s.busy?'disabled':''}>${s.busy?'训练运行中…':'开始实际训练'}</button><button class="btn" data-studio="weights" ${!s.fit?'disabled':''}>↓ 参数 / 权重</button></div><div class="status" id="studio-status" role="status">${esc(s.status)}${s.fit?' · '+num(s.fit.duration,3)+'秒':''}</div><div class="row gap"><button class="btn" data-studio="eval" data-id="1" ${!s.fit||s.busy?'disabled':''}>验证集评价</button><button class="btn" data-studio="eval" data-id="2" ${!s.fit||s.busy?'disabled':''}>独立测试集评价</button><span class="tag">${s.evalRole??'尚未评价'}</span></div><div style="margin-top:17px">${metricView(s)}</div><div class="gap">${chart([{name:'训练损失',values:s.fit?.history?.map(r=>r.loss)??[],color:'#aa2834'},{name:'验证损失',values:s.fit?.history?.map(r=>r.val_loss)??[],color:'#4a7eab',dash:true}],{unit:'损失值',label:'轮次 / 树迭代'})}</div><p class="tiny">数理拟合和无监督树不产生神经网络训练损失；不补画虚构曲线。测试集只用于独立评价。</p>${resultView(s)}`;}
function calcView(m,s){return `<div class="note">计算使用当前已训练参数。回归树和LSTM使用此前历史预测次日产油；TCN按所上传连续窗口计算，不自动等价于多步未来预测。</div><div class="file-box"><label for="calc-file">计算输入 CSV / JSON</label><input type="file" id="calc-file" data-upload="calc" accept=".csv,.json"><small>推理可省略目标标签；特征字段及单位见右侧</small></div><div class="row gap"><button class="btn" data-studio="calc-test">使用当前测试集</button><button class="btn primary" data-studio="predict" ${!s.fit||s.busy?'disabled':''}>运行模型计算</button><button class="btn" data-studio="results" ${!s.results.length?'disabled':''}>↓ 完整结果CSV</button></div><div class="status">${esc(s.status)}</div>${resultView(s)}`;}
function invalidate(s){s.fit?.network?.dispose?.();s.fit=null;s.results=[];s.metrics=null;s.status='数据已变更，请重新训练';}
function checkRows(m,rows){validateRows(rows,m.required);if(rows.length<3)throw Error('至少需要3条记录');}
export async function studioAction(action,id,{render,remote,notify}){const m=MODELS.find(m=>m.id===modelId),s=state();if(['load','split','train'].includes(action)&&s.busy){notify('模型正在训练，请等待完成后再修改数据');return;}s.error='';try{if(['load','split','train'].includes(action))assertExperimentWritable(s);if(action==='model'){modelId=id;tab='data';render();return;}if(action==='tab'){tab=id;render();return;}if(action==='load'){const ds=DATASETS.find(d=>d.id===document.getElementById('studio-dataset').value);s.dataset=ds.id;const r=await fetch(ds.path);if(!r.ok)throw Error('数据载入失败');const rows=await r.json();checkRows(m,rows);invalidate(s);s.all=rows;s.origin=ds.name+' · '+ds.source;s.method=['event3w','esp','effect'].includes(m.id)?'random':['tracer','horner'].includes(m.id)?'well-time':'well-time';s.sets=partition(rows,s.ratio,s.method);s.status='已载入'+rows.length+'行';}
 else if(action==='split'){s.ratio=[0,1,2].map(i=>Number(document.getElementById('ratio'+i).value));s.method=document.getElementById('split-method').value;if(!s.all.length)throw Error('请先载入或上传整体数据');const out=partition(s.all,s.ratio,s.method);invalidate(s);s.sets=out;}
 else if(action==='train'){if(s.busy)return;assertDisjoint(s.sets);checkRows(m,s.sets[0]);if(!s.sets[1].length||!s.sets[2].length)throw Error('请补充独立验证集与测试集');s.options={epochs:Math.max(1,Math.min(100,Number(document.getElementById('epochs').value)||10)),trees:Math.max(1,Math.min(100,Number(document.getElementById('trees').value)||30)),depth:Math.max(1,Math.min(5,Number(document.getElementById('depth').value)||3))};invalidate(s);s.busy=true;s.status='训练中…';render();await new Promise(r=>setTimeout(r,30));s.fit=await trainer.train(m,s.sets[0],s.sets[1],s.options,(p,logs)=>{s.status='训练进度 '+Math.round(p*100)+'% · loss='+num(logs?.loss,5);const el=document.getElementById('studio-status');if(el)el.textContent=s.status;},remote);s.status='训练完成 · '+s.fit.trainedRows+'行；耗时';s.busy=false;notify('实际训练完成，请选择独立评价集');}
 else if(action==='eval'){if(!s.fit)throw Error('请先训练');const role=Number(id),rows=s.sets[role];if(!rows.length)throw Error('当前评价集为空');s.results=await trainer.predict(m,s.fit,rows,role===1?s.sets[0]:[...s.sets[0],...s.sets[1]],remote);s.metrics=trainer.metrics(m,s.fit,s.results);s.evalRole=role===1?'验证集指标':'独立测试指标';s.status=s.evalRole+' · 有效输出'+s.results.filter(r=>finite(r.prediction)).length+'条';}
 else if(action==='calc-test'){s.calc=s.sets[2];s.status='计算输入采用当前测试集'+s.calc.length+'行';}
 else if(action==='predict'){if(!s.fit)throw Error('请先训练');if(!s.calc?.length)throw Error('请上传计算输入或选择测试集');s.results=await trainer.predict(m,s.fit,s.calc,[...s.sets[0],...s.sets[1]],remote);s.status='计算完成 · '+s.results.length+'条';}
 else if(action==='results'){downloadRows(m.id+'-results.csv',s.results);return;}
 else if(action==='weights'){if(!s.fit)throw Error('尚未训练');download(m.id+'-model.json',JSON.stringify({model:m.id,source:s.origin,ratio:s.ratio,...await trainer.serialize(m,s.fit)},null,2),'application/json');return;}
 else if(action==='export-split'){download(m.id+'-splits.json',JSON.stringify({model:m.id,source:s.origin,method:s.method,ratios:s.ratio,train:s.sets[0],validation:s.sets[1],test:s.sets[2]},null,2),'application/json');return;}
 }catch(e){s.error=e.message;s.busy=false;notify(e.message);}render();}
export async function studioUpload(role,file,{render,notify}){const m=MODELS.find(m=>m.id===modelId),s=state();try{assertExperimentWritable(s);const rows=await readFile(file);assertExperimentWritable(s);if(role==='calc'){s.calc=rows;s.status='已载入计算输入'+rows.length+'行';}else{checkRows(m,rows);if(role==='all'){const sets=partition(rows,s.ratio,s.method);invalidate(s);s.all=rows;s.sets=sets;s.origin='用户上传：'+file.name;}else{const sets=s.sets.map((r,i)=>i===Number(role)?rows:r);assertDisjoint(sets);invalidate(s);s.sets=sets;s.all=[];s.origin='用户分别上传（请自行核实现场来源与标签）';}}s.error='';notify('数据载入完成');}catch(e){s.error=e.message;notify(e.message);}render();}
